result:
.devRenCon {
  width: 100%;
  height: 100%;
}
.formLabel {
  line-height: 16px;
  display: block;
}

.head_p{

  height: 160px;
  display: flex;
  justify-content: center;
  align-items: center;
  .headContent{
    display: flex;
    flex-direction: row;
    justify-content: center;
    align-items: center;
    margin-right: 40px;
    height:80px;
    img{
      width:60px;
      height:60px;
    }
    .num_content{
      display: flex;
      flex-direction: column;
       justify-content: center;
      align-items: center;
      margin: 10px 20px;
      .title{
        font-size: 14px;
      }
      .num{
        color: #409EFF;
        font-size: 20px;
        font-weight: 500;
      }
    }

  }
}

.info_form{

    display: flex;
    align-items: center;
    padding-left: 10px;
    flex-direction: row;
    .form_box{
      width: 100%;
      .form_item{
        display: flex;
        flex-direction: row;
        .form_label{
          line-height: 40px;
          font-size: 14px;
          white-space: nowrap;
          position: relative;
        }
        .form_content{
          flex: auto;
          overflow-x: hidden;
          line-height: 40px;
          font-size: 14px;
          padding-left: 15px;
        }
      }
    }
  }

.approve_status{
  display: flex;
  justify-content: center;
  align-items: center;
  height: 120px;
  img{
    width:88px;
    height: 77px;
  }
}
